declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    elementCount : DINT := 0;
    status : WORD := 16#0000;
END_VAR
VAR_IN_OUT
    item : VARIANT;
    buffer : VARIANT;
END_VAR
VAR
    prevEnqueue : BOOL := FALSE;
    prevDequeue : BOOL := FALSE;
    capacity : DINT := 0;
END_VAR

implementation:
status := 16#0000;
IF reset THEN
    elementCount := 0;
ELSIF enqueue AND NOT prevEnqueue THEN
    capacity := UPPER_BOUND(buffer, 1) - LOWER_BOUND(buffer, 1) + 1;
    IF elementCount >= capacity THEN
        status := 16#8002;
    ELSE
        elementCount := elementCount + 1;
        status := 16#0000;
    END_IF;
ELSIF dequeue AND NOT prevDequeue THEN
    IF elementCount = 0 THEN
        status := 16#8001;
    ELSE
        elementCount := elementCount - 1;
        status := 16#0000;
    END_IF;
END_IF;

prevEnqueue := enqueue;
prevDequeue := dequeue;
